        public void ConsultationRequestCreation_ShouldCreateOfflineConsultationFile()
        {
            // Arrange
            var patient = new Patient();
            patient.SetSymptoms("Headache");
            patient.UploadReport("MRI.jpg");
            patient.SetMode("Offline");

            // Act
            var offlineConsultationFile = PatientAppointmentFile.Create(patient);

            // Assert
            Assert.True(offlineConsultationFile.Exists());
        }

        [Fact]
        public void ConsultationRequestCreation_ShouldBatchCreateAppointmentFilesForNext5Days()
        {
            // Arrange
            var patient = new Patient();
            patient.SetSymptoms("Headache");
            patient.UploadReport("MRI.jpg");
            patient.SetMode("Appointment");

            // Act
            var appointmentFiles = PatientAppointmentFile.BatchCreate(patient, 5);

            // Assert
            Assert.True(appointmentFiles.Count == 5);
        }

